IRFCO2[t_, aC1_, aC2_, aC3_, aC4_, tauC1_, tauC2_, tauC3_] = 
    aC1 + aC2/E^(t/tauC1) + aC3/E^(t/tauC2) + aC4/E^(t/tauC3)
 
IRFNonCO2[t_, tauNonCO2_] = E^(-(t/tauNonCO2))
 
IRFPulseT[t_, kPulseT_, aT1_, tauT1_, aT2_, tauT2_] = 
    kPulseT*(aT1/(E^(t/tauT1)*tauT1) + aT2/(E^(t/tauT2)*tauT2))
 
IRFCCfdbk[t_, gamma_, aS1_, aS2_, aS3_, tauS1_, tauS2_, tauS3_] = 
    gamma*(-(aS1/(E^(t/tauS1)*tauS1)) - aS2/(E^(t/tauS2)*tauS2) - 
      aS3/(E^(t/tauS3)*tauS3) + DiracDelta[t])
 
C0[t_] = -DiracDelta[t]
 
C1[t_, a_, v1_, v2_, rotation_] = Piecewise[
     {{-(a*(E^(-(t*v1)) - E^(-(t*v2)))), 0 <= t <= rotation}}, 0]
 
C2[t_, rotation_] = Piecewise[{{(-2*(rotation - t))/rotation^2, 
       0 <= t <= rotation}}, 0]
 
C3[t_, rotation_] = Piecewise[{{-rotation^(-1), 0 <= t <= rotation}}, 0]
 
E1[t_, decay_] = Piecewise[{{3/(decay*E^((3*t)/decay)), 0 <= t}}, 0]
 
E2[t_, decay_] = Piecewise[{{(2*(decay - t))/decay^2, 0 <= t <= decay}}, 0]
 
E3[t_, decay_] = Piecewise[{{decay^(-1), 0 <= t <= decay}}, 0]
 
F1[t_, decay_] = 3/(decay*E^((3*t)/decay)) - DiracDelta[t]
 
F2[t_, decay_] = -DiracDelta[t] + Piecewise[
      {{(2*(decay - t))/decay^2, t <= decay}}, 0]
 
F3[t_, decay_] = -DiracDelta[t] + Piecewise[{{decay^(-1), t <= decay}}, 0]
 
F4[t_, decay_, a_, v1_, v2_, rotation_] = 
    Piecewise[{{a*(-E^(-(t*v1)) + E^(-(t*v2))), rotation >= t}}, 
     (3*E^((3*(rotation - t))/decay))/decay]
 
F5[t_, decay_, a_, v1_, v2_, rotation_] = 
    Piecewise[{{a*(-E^(-(t*v1)) + E^(-(t*v2))), rotation >= t}, 
      {0, rotation >= t || decay + rotation < t}}, (2*(decay + rotation - t))/
      decay^2]
 
F6[t_, decay_, a_, v1_, v2_, rotation_] = 
    Piecewise[{{a*(-E^(-(t*v1)) + E^(-(t*v2))), rotation >= t}, 
      {0, rotation >= t || decay + rotation < t}}, decay^(-1)]
 
F7[t_, decay_, rotation_] = Piecewise[{{(-2*(rotation - t))/rotation^2, 
       rotation >= t}}, (3*E^((3*(rotation - t))/decay))/decay]
 
F8[t_, decay_, rotation_] = Piecewise[{{(-2*(rotation - t))/rotation^2, 
       rotation >= t}, {0, rotation >= t || decay + rotation < t}}, 
     (2*(decay + rotation - t))/decay^2]
 
F9[t_, decay_, rotation_] = Piecewise[{{(-2*(rotation - t))/rotation^2, 
       rotation >= t}, {0, rotation >= t || decay + rotation < t}}, 
     decay^(-1)]
 
F10[t_, decay_, rotation_] = Piecewise[{{-rotation^(-1), rotation >= t}}, 
     (3*E^((3*(rotation - t))/decay))/decay]
 
F11[t_, decay_, rotation_] = Piecewise[{{-rotation^(-1), rotation >= t}, 
      {0, rotation >= t || decay + rotation < t}}, (2*(decay + rotation - t))/
      decay^2]
 
F12[t_, decay_, rotation_] = Piecewise[{{-rotation^(-1), rotation >= t}, 
      {0, rotation >= t || decay + rotation < t}}, decay^(-1)]
 
F13[t_, decay_, p_, rotation_] = Piecewise[
     {{Piecewise[{{(-2*t)/(p*rotation), t < p}, {-2/rotation, p == t}, 
         {(2*(rotation - t))/((p - rotation)*rotation), Inequality[p, Less, 
           t, LessEqual, rotation]}}, 0], t <= rotation}, 
      {(3*E^((3*(rotation - t))/decay))/decay, t > rotation}}, 0]
 
F14[t_, decay_, p_, rotation_] = Piecewise[
     {{(-2*t)/(p*rotation), rotation >= t && p > t}, 
      {-2/rotation, rotation >= t && p == t}, 
      {(2*(rotation - t))/((p - rotation)*rotation), rotation >= t && p < t}, 
      {0, rotation >= t || decay + rotation < t}}, (2*(decay + rotation - t))/
      decay^2]
 
F15[t_, decay_, p_, rotation_] = Piecewise[
     {{(-2*t)/(p*rotation), rotation >= t && p > t}, 
      {-2/rotation, rotation >= t && p == t}, 
      {(2*(rotation - t))/((p - rotation)*rotation), rotation >= t && p < t}, 
      {0, rotation >= t || decay + rotation < t}}, decay^(-1)]
 
F16[t_, decay_] = -DiracDelta[t] + DiracDelta[-decay + t]
 
F17[t_, decay_, rotation_] = DiracDelta[decay + rotation - t] + 
     Piecewise[{{-rotation^(-1), t <= rotation}}, 0]
 
F18[t_, decay_, p_, rotation_] = DiracDelta[decay + rotation - t] + 
     Piecewise[{{(-2*t)/(p*rotation), t < p}, {-2/rotation, p == t}, 
       {(2*(rotation - t))/((p - rotation)*rotation), Inequality[p, Less, t, 
         LessEqual, rotation]}}, 0]
 
PRFF1[t_, decay_, aC1_, aC2_, aC3_, aC4_, tauC1_, tauC2_, tauC3_] = 
    (-(aC1/E^((3*t)/decay)) + (aC2*(-(decay/E^(t/tauC1)) + 
         (3*tauC1)/E^((3*t)/decay)))/(decay - 3*tauC1) - 
      (aC3*decay)/(E^(t/tauC2)*(decay - 3*tauC2)) + 
      (3*aC3*tauC2)/(E^((3*t)/decay)*(decay - 3*tauC2)) - 
      (aC4*decay)/(E^(t/tauC3)*(decay - 3*tauC3)) + 
      (3*aC4*tauC3)/(E^((3*t)/decay)*(decay - 3*tauC3)))*UnitStep[t]
 
PRFF2[t_, decay_, aC1_, aC2_, aC3_, aC4_, tauC1_, tauC2_, tauC3_] = 
    Piecewise[{{aC1 - (2*(aC2*E^(t*(tauC2^(-1) + tauC3^(-1)))*tauC1*
             (decay + tauC1 - E^(decay/tauC1)*tauC1) + E^(t/tauC1)*
             (aC3*E^(t/tauC3)*tauC2*(decay + tauC2 - E^(decay/tauC2)*tauC2) + 
              aC4*E^(t/tauC2)*tauC3*(decay + tauC3 - E^(decay/tauC3)*
                 tauC3))))/(decay^2*E^(t*(tauC1^(-1) + tauC2^(-1) + 
              tauC3^(-1)))), decay > 0 && decay < t}, 
       {(-(aC1*t*(-2*decay + t)) + 2*(aC2*tauC1*(decay - decay/E^(t/tauC1) - 
              t + tauC1 - tauC1/E^(t/tauC1)) + aC3*tauC2*
             (decay - decay/E^(t/tauC2) - t + tauC2 - tauC2/E^(t/tauC2)) + 
            aC4*tauC3*(decay - decay/E^(t/tauC3) - t + tauC3 - 
              tauC3/E^(t/tauC3))))/decay^2, decay > 0 && t > 0 && 
         decay >= t}}, 0] - (aC1 + aC2/E^(t/tauC1) + aC3/E^(t/tauC2) + 
       aC4/E^(t/tauC3))*UnitStep[t]
 
PRFF3[t_, decay_, aC1_, aC2_, aC3_, aC4_, tauC1_, tauC2_, tauC3_] = 
    Piecewise[{{(aC1*decay + aC2*E^((decay - t)/tauC1)*tauC1 - 
          (aC2*tauC1)/E^(t/tauC1) + aC3*E^((decay - t)/tauC2)*tauC2 - 
          (aC3*tauC2)/E^(t/tauC2) + aC4*E^((decay - t)/tauC3)*tauC3 - 
          (aC4*tauC3)/E^(t/tauC3))/decay, decay > 0 && decay < t}, 
       {(aC1*t + aC2*tauC1 - (aC2*tauC1)/E^(t/tauC1) + aC3*tauC2 - 
          (aC3*tauC2)/E^(t/tauC2) + aC4*tauC3 - (aC4*tauC3)/E^(t/tauC3))/
         decay, decay > 0 && t > 0 && decay >= t}}, 0] - 
     (aC1 + aC2/E^(t/tauC1) + aC3/E^(t/tauC2) + aC4/E^(t/tauC3))*UnitStep[t]
 
PRFF4[t_, decay_, aC1_, aC2_, aC3_, aC4_, tauC1_, tauC2_, tauC3_, a_, v1_, 
     v2_, rotation_] = Piecewise[
     {{(a*((aC1*E^(t*v2))/v1 - (aC1*E^(t*v1))/v2 + 
          (aC1*E^(t*(v1 + v2))*(v1 - v2))/(v1*v2) - 
          (aC2*tauC1*(E^(t*v1)*(-1 + tauC1*v1) - 
             E^((t*(-1 + tauC1*(v1 + v2)))/tauC1)*tauC1*(v1 - v2) + 
             E^(t*v2)*(1 - tauC1*v2)))/((-1 + tauC1*v1)*(-1 + tauC1*v2)) - 
          (aC3*tauC2*(E^(t*v1)*(-1 + tauC2*v1) - 
             E^((t*(-1 + tauC2*(v1 + v2)))/tauC2)*tauC2*(v1 - v2) + 
             E^(t*v2)*(1 - tauC2*v2)))/((-1 + tauC2*v1)*(-1 + tauC2*v2)) - 
          (aC4*tauC3*(E^(t*v1)*(-1 + tauC3*v1) - 
             E^((t*(-1 + tauC3*(v1 + v2)))/tauC3)*tauC3*(v1 - v2) + 
             E^(t*v2)*(1 - tauC3*v2)))/((-1 + tauC3*v1)*(-1 + tauC3*v2))))/
        E^(t*(v1 + v2)), rotation >= t && t > 0}, 
      {(aC1*E^(t*(-3/decay + tauC1^(-1) + tauC2^(-1) + tauC3^(-1)))*
          (-E^((3*rotation)/decay) + E^((3*t)/decay)) + 
         (3*aC2*E^(t*(-3/decay + tauC2^(-1) + tauC3^(-1)))*
           (-E^((3*t)/decay + rotation/tauC1) + E^((3*rotation)/decay + 
              t/tauC1))*tauC1)/(decay - 3*tauC1) + 
         (3*E^(t*(-3/decay + tauC1^(-1)))*(aC4*E^(t/tauC2)*
             (E^((3*t)/decay + rotation/tauC3) - E^((3*rotation)/decay + 
                t/tauC3))*(-decay + 3*tauC2)*tauC3 + aC3*E^(t/tauC3)*
             (E^((3*t)/decay + rotation/tauC2) - E^((3*rotation)/decay + 
                t/tauC2))*tauC2*(-decay + 3*tauC3)))/((decay - 3*tauC2)*
           (decay - 3*tauC3)) + 
         (a*aC1*E^(t*(tauC1^(-1) + tauC2^(-1) + tauC3^(-1)) - 
             rotation*(v1 + v2))*(-(E^(rotation*v1)*v1) + 
            E^(rotation*(v1 + v2))*(v1 - v2) + E^(rotation*v2)*v2))/(v1*v2) + 
         (a*(-((aC2*E^(t*(tauC2^(-1) + tauC3^(-1)))*tauC1*(
                E^(rotation*(tauC1^(-1) + v1))*(-1 + tauC1*v1) - 
                E^(rotation*(v1 + v2))*tauC1*(v1 - v2) + 
                E^(rotation*(tauC1^(-1) + v2))*(1 - tauC1*v2)))/
              ((-1 + tauC1*v1)*(-1 + tauC1*v2))) - 
            (aC3*E^(t*(tauC1^(-1) + tauC3^(-1)))*tauC2*
              (E^(rotation*(tauC2^(-1) + v1))*(-1 + tauC2*v1) - 
               E^(rotation*(v1 + v2))*tauC2*(v1 - v2) + E^(rotation*
                  (tauC2^(-1) + v2))*(1 - tauC2*v2)))/((-1 + tauC2*v1)*
              (-1 + tauC2*v2)) - (aC4*E^(t*(tauC1^(-1) + tauC2^(-1)))*tauC3*
              (E^(rotation*(tauC3^(-1) + v1))*(-1 + tauC3*v1) - 
               E^(rotation*(v1 + v2))*tauC3*(v1 - v2) + E^(rotation*
                  (tauC3^(-1) + v2))*(1 - tauC3*v2)))/((-1 + tauC3*v1)*
              (-1 + tauC3*v2))))/E^(rotation*(v1 + v2)))/
        E^(t*(tauC1^(-1) + tauC2^(-1) + tauC3^(-1))), rotation < t}}, 0]
 
PRFF5[t_, decay_, aC1_, aC2_, aC3_, aC4_, tauC1_, tauC2_, tauC3_, a_, v1_, 
     v2_, rotation_] = Piecewise[
     {{(a*((aC1*E^(t*v2))/v1 - (aC1*E^(t*v1))/v2 + 
          (aC1*E^(t*(v1 + v2))*(v1 - v2))/(v1*v2) - 
          (aC2*tauC1*(E^(t*v1)*(-1 + tauC1*v1) - 
             E^((t*(-1 + tauC1*(v1 + v2)))/tauC1)*tauC1*(v1 - v2) + 
             E^(t*v2)*(1 - tauC1*v2)))/((-1 + tauC1*v1)*(-1 + tauC1*v2)) - 
          (aC3*tauC2*(E^(t*v1)*(-1 + tauC2*v1) - 
             E^((t*(-1 + tauC2*(v1 + v2)))/tauC2)*tauC2*(v1 - v2) + 
             E^(t*v2)*(1 - tauC2*v2)))/((-1 + tauC2*v1)*(-1 + tauC2*v2)) - 
          (aC4*tauC3*(E^(t*v1)*(-1 + tauC3*v1) - 
             E^((t*(-1 + tauC3*(v1 + v2)))/tauC3)*tauC3*(v1 - v2) + 
             E^(t*v2)*(1 - tauC3*v2)))/((-1 + tauC3*v1)*(-1 + tauC3*v2))))/
        E^(t*(v1 + v2)), rotation >= t && decay + rotation >= t && t > 0}, 
      {((aC1*E^(t*(tauC1^(-1) + tauC2^(-1) + tauC3^(-1)))*
           (2*decay + rotation - t)*(-rotation + t))/decay^2 + 
         (2*aC2*E^(t*(tauC2^(-1) + tauC3^(-1)))*tauC1*
           (decay*(-E^(rotation/tauC1) + E^(t/tauC1)) - E^(rotation/tauC1)*
             tauC1 + E^(t/tauC1)*(rotation - t + tauC1)))/decay^2 + 
         (2*E^(t/tauC1)*(aC3*E^(t/tauC3)*tauC2*(decay*(-E^(rotation/tauC2) + 
                E^(t/tauC2)) - E^(rotation/tauC2)*tauC2 + E^(t/tauC2)*(
                rotation - t + tauC2)) + aC4*E^(t/tauC2)*tauC3*
             (decay*(-E^(rotation/tauC3) + E^(t/tauC3)) - E^(rotation/tauC3)*
               tauC3 + E^(t/tauC3)*(rotation - t + tauC3))))/decay^2 + 
         (a*aC1*E^(t*(tauC1^(-1) + tauC2^(-1) + tauC3^(-1)) - 
             rotation*(v1 + v2))*(-(E^(rotation*v1)*v1) + 
            E^(rotation*(v1 + v2))*(v1 - v2) + E^(rotation*v2)*v2))/(v1*v2) + 
         (a*(-((aC2*E^(t*(tauC2^(-1) + tauC3^(-1)))*tauC1*(
                E^(rotation*(tauC1^(-1) + v1))*(-1 + tauC1*v1) - 
                E^(rotation*(v1 + v2))*tauC1*(v1 - v2) + 
                E^(rotation*(tauC1^(-1) + v2))*(1 - tauC1*v2)))/
              ((-1 + tauC1*v1)*(-1 + tauC1*v2))) - 
            (aC3*E^(t*(tauC1^(-1) + tauC3^(-1)))*tauC2*
              (E^(rotation*(tauC2^(-1) + v1))*(-1 + tauC2*v1) - 
               E^(rotation*(v1 + v2))*tauC2*(v1 - v2) + E^(rotation*
                  (tauC2^(-1) + v2))*(1 - tauC2*v2)))/((-1 + tauC2*v1)*
              (-1 + tauC2*v2)) - (aC4*E^(t*(tauC1^(-1) + tauC2^(-1)))*tauC3*
              (E^(rotation*(tauC3^(-1) + v1))*(-1 + tauC3*v1) - 
               E^(rotation*(v1 + v2))*tauC3*(v1 - v2) + E^(rotation*
                  (tauC3^(-1) + v2))*(1 - tauC3*v2)))/((-1 + tauC3*v1)*
              (-1 + tauC3*v2))))/E^(rotation*(v1 + v2)))/
        E^(t*(tauC1^(-1) + tauC2^(-1) + tauC3^(-1))), 
       rotation < t && decay + rotation >= t}, 
      {aC1 - (2*(aC2*E^(rotation/tauC1 + t*(tauC2^(-1) + tauC3^(-1)))*tauC1*
            (decay + tauC1 - E^(decay/tauC1)*tauC1) + E^(t/tauC1)*
            (aC3*E^(rotation/tauC2 + t/tauC3)*tauC2*(decay + tauC2 - 
               E^(decay/tauC2)*tauC2) + aC4*E^(t/tauC2 + rotation/tauC3)*
              tauC3*(decay + tauC3 - E^(decay/tauC3)*tauC3))))/
         (decay^2*E^(t*(tauC1^(-1) + tauC2^(-1) + tauC3^(-1)))) + 
        (a*aC1*(v1 - v1/E^(rotation*v2) + (-1 + E^(-(rotation*v1)))*v2))/
         (v1*v2) + a*E^(-2*t*(tauC1^(-1) + tauC2^(-1) + tauC3^(-1)) - 
           rotation*(v1 + v2))*
         (-((aC2*E^(t*(tauC1^(-1) + 2*(tauC2^(-1) + tauC3^(-1))))*tauC1*
             (E^(rotation*(tauC1^(-1) + v1))*(-1 + tauC1*v1) - 
              E^(rotation*(v1 + v2))*tauC1*(v1 - v2) + 
              E^(rotation*(tauC1^(-1) + v2))*(1 - tauC1*v2)))/
            ((-1 + tauC1*v1)*(-1 + tauC1*v2))) - 
          (aC3*E^(t*(2/tauC1 + tauC2^(-1) + 2/tauC3))*tauC2*
            (E^(rotation*(tauC2^(-1) + v1))*(-1 + tauC2*v1) - 
             E^(rotation*(v1 + v2))*tauC2*(v1 - v2) + 
             E^(rotation*(tauC2^(-1) + v2))*(1 - tauC2*v2)))/
           ((-1 + tauC2*v1)*(-1 + tauC2*v2)) - 
          (aC4*E^(t*(2/tauC1 + 2/tauC2 + tauC3^(-1)))*tauC3*
            (E^(rotation*(tauC3^(-1) + v1))*(-1 + tauC3*v1) - 
             E^(rotation*(v1 + v2))*tauC3*(v1 - v2) + 
             E^(rotation*(tauC3^(-1) + v2))*(1 - tauC3*v2)))/
           ((-1 + tauC3*v1)*(-1 + tauC3*v2))), rotation < t && 
        decay + rotation < t}}, 0]
 
PRFF6[t_, decay_, aC1_, aC2_, aC3_, aC4_, tauC1_, tauC2_, tauC3_, a_, v1_, 
     v2_, rotation_] = Piecewise[
     {{(a*((aC1*E^(t*v2))/v1 - (aC1*E^(t*v1))/v2 + 
          (aC1*E^(t*(v1 + v2))*(v1 - v2))/(v1*v2) - 
          (aC2*tauC1*(E^(t*v1)*(-1 + tauC1*v1) - 
             E^((t*(-1 + tauC1*(v1 + v2)))/tauC1)*tauC1*(v1 - v2) + 
             E^(t*v2)*(1 - tauC1*v2)))/((-1 + tauC1*v1)*(-1 + tauC1*v2)) - 
          (aC3*tauC2*(E^(t*v1)*(-1 + tauC2*v1) - 
             E^((t*(-1 + tauC2*(v1 + v2)))/tauC2)*tauC2*(v1 - v2) + 
             E^(t*v2)*(1 - tauC2*v2)))/((-1 + tauC2*v1)*(-1 + tauC2*v2)) - 
          (aC4*tauC3*(E^(t*v1)*(-1 + tauC3*v1) - 
             E^((t*(-1 + tauC3*(v1 + v2)))/tauC3)*tauC3*(v1 - v2) + 
             E^(t*v2)*(1 - tauC3*v2)))/((-1 + tauC3*v1)*(-1 + tauC3*v2))))/
        E^(t*(v1 + v2)), rotation >= t && decay + rotation >= t && t > 0}, 
      {aC1 + (aC2*E^((rotation - t)/tauC1)*(-1 + E^(decay/tauC1))*tauC1)/
         decay + (aC3*E^(rotation/tauC2 + t/tauC3)*(-1 + E^(decay/tauC2))*
           tauC2 + aC4*E^(t/tauC2 + rotation/tauC3)*(-1 + E^(decay/tauC3))*
           tauC3)/(decay*E^(t*(tauC2^(-1) + tauC3^(-1)))) + 
        (a*aC1*(v1 - v1/E^(rotation*v2) + (-1 + E^(-(rotation*v1)))*v2))/
         (v1*v2) + a*E^(-(t*(tauC1^(-1) + tauC2^(-1) + tauC3^(-1))) - 
           rotation*(v1 + v2))*(-((aC2*E^(t*(tauC2^(-1) + tauC3^(-1)))*tauC1*
             (E^(rotation*(tauC1^(-1) + v1))*(-1 + tauC1*v1) - 
              E^(rotation*(v1 + v2))*tauC1*(v1 - v2) + 
              E^(rotation*(tauC1^(-1) + v2))*(1 - tauC1*v2)))/
            ((-1 + tauC1*v1)*(-1 + tauC1*v2))) - 
          (aC3*E^(t*(tauC1^(-1) + tauC3^(-1)))*tauC2*
            (E^(rotation*(tauC2^(-1) + v1))*(-1 + tauC2*v1) - 
             E^(rotation*(v1 + v2))*tauC2*(v1 - v2) + 
             E^(rotation*(tauC2^(-1) + v2))*(1 - tauC2*v2)))/
           ((-1 + tauC2*v1)*(-1 + tauC2*v2)) - 
          (aC4*E^(t*(tauC1^(-1) + tauC2^(-1)))*tauC3*
            (E^(rotation*(tauC3^(-1) + v1))*(-1 + tauC3*v1) - 
             E^(rotation*(v1 + v2))*tauC3*(v1 - v2) + 
             E^(rotation*(tauC3^(-1) + v2))*(1 - tauC3*v2)))/
           ((-1 + tauC3*v1)*(-1 + tauC3*v2))), rotation < t && 
        decay + rotation < t}, 
      {((aC1*E^(t*(tauC1^(-1) + tauC2^(-1) + tauC3^(-1)))*(-rotation + t))/
          decay - (aC2*E^(t*(tauC2^(-1) + tauC3^(-1)))*(E^(rotation/tauC1) - 
            E^(t/tauC1))*tauC1)/decay + 
         (E^(t/tauC1)*(aC3*E^(t/tauC3)*(-E^(rotation/tauC2) + E^(t/tauC2))*
             tauC2 + aC4*E^(t/tauC2)*(-E^(rotation/tauC3) + E^(t/tauC3))*
             tauC3))/decay + (a*aC1*E^(t*(tauC1^(-1) + tauC2^(-1) + tauC3^
                (-1)) - rotation*(v1 + v2))*(-(E^(rotation*v1)*v1) + 
            E^(rotation*(v1 + v2))*(v1 - v2) + E^(rotation*v2)*v2))/(v1*v2) + 
         (a*(-((aC2*E^(t*(tauC2^(-1) + tauC3^(-1)))*tauC1*(
                E^(rotation*(tauC1^(-1) + v1))*(-1 + tauC1*v1) - 
                E^(rotation*(v1 + v2))*tauC1*(v1 - v2) + 
                E^(rotation*(tauC1^(-1) + v2))*(1 - tauC1*v2)))/
              ((-1 + tauC1*v1)*(-1 + tauC1*v2))) - 
            (aC3*E^(t*(tauC1^(-1) + tauC3^(-1)))*tauC2*
              (E^(rotation*(tauC2^(-1) + v1))*(-1 + tauC2*v1) - 
               E^(rotation*(v1 + v2))*tauC2*(v1 - v2) + E^(rotation*
