AGWPPRFF1[t_, aC1_, aC2_, aC3_, aC4_, tauC1_, tauC2_, tauC3_, AACO2_, 
     decay_] = (AACO2*decay*(aC1*(-1 + E^((-3*t)/decay)) - 
       (3*aC2*(E^((-3*t)/decay) - E^(-(t/tauC1)))*tauC1)/(decay - 3*tauC1) + 
       (3*(aC3*E^(t/tauC3)*(E^((3*t)/decay) - E^(t/tauC2))*tauC2*
           (decay - 3*tauC3) + aC4*E^(t/tauC2)*(E^((3*t)/decay) - 
            E^(t/tauC3))*(decay - 3*tauC2)*tauC3))/
        (E^(t*(3/decay + tauC2^(-1) + tauC3^(-1)))*(decay - 3*tauC2)*
         (decay - 3*tauC3))))/3
 
AGWPPRFF2[t_, aC1_, aC2_, aC3_, aC4_, tauC1_, tauC2_, tauC3_, AACO2_, 
     decay_] = AACO2*(-(aC1*t) - aC2*tauC1 + (aC2*tauC1)/E^(t/tauC1) - 
