iAGTPPRFF1[TH_, aC1_, aC2_, aC3_, aC4_, tauC1_, tauC2_, tauC3_, kPulseT_, 
     aT1_, tauT1_, aT2_, tauT2_, AACO2_, decay_] = 
    (AACO2*kPulseT*(aC1*aT1*decay*(-1 + E^((-3*TH)/decay)) + 
       aC1*aT2*decay*(-1 + E^((-3*TH)/decay)) - 
